B.PE=new A.a5(B.a0,["Kael! Voc\xea me achou! Agora a gente corre junto \u2014 ningu\xe9m me alcan\xe7a!","Kael! You found me! Now we run together \u2014 no one can catch me!","\xa1Kael! \xa1Me encontraste! Ahora corremos juntos, \xa1nadie me alcanza!"],t.w)
B.PU=new A.a5(B.a0,["Ufa! Meu canh\xe3o estava louco para sair daqui. Bora derrubar uns chefes!","Phew! My cannon was dying to get out of here. Let's take down some bosses!","\xa1Uf! Mi ca\xf1\xf3n ten\xeda muchas ganas de salir. \xa1Vamos a derribar jefes!"],t.w)
B.PQ=new A.a5(B.a0,["Eu avisei que ia dar errado, n\xe9? Valeu, parceiro. Minha mira \xe9 sua!","I told you it would go wrong, right? Thanks, partner. My aim is yours!","Te dije que saldr\xeda mal, \xbfno? Gracias, compa\xf1ero. \xa1Mi punter\xeda es tuya!"],t.w)
B.PC=new A.a5(B.a0,["Senti sua energia chegando. Juntos, nada vai nos parar.","I felt your energy coming. Together, nothing can stop us.","Sent\xed tu energ\xeda llegando. Juntos, nada nos detendr\xe1."],t.w)
B.Pk=new A.a5(B.kB,[B.PE,B.PU,B.PQ,B.PC],t.vb)
B.PN=new A.a5(B.a0,["{r}! Aqui, nesta jaula! O Imperador me trancou e jogou a chave fora!","{r}! Over here, in this cage! The Emperor locked me up and threw away the key!","\xa1{r}! \xa1Aqu\xed, en esta jaula! \xa1El Emperador me encerr\xf3 y tir\xf3 la llave!"],t.w)
B.PP=new A.a5(B.a0,["Ei, {r}! Me tira daqui! Meu canh\xe3o est\xe1 doido para explodir essa jaula!","Hey, {r}! Get me out! My cannon is dying to blast this cage!","\xa1Oye, {r}! \xa1S\xe1came de aqu\xed! \xa1Mi ca\xf1\xf3n quiere volar esta jaula!"],t.w)
B.PK=new A.a5(B.a0,["{r}? Eu sabia que voc\xea vinha! R\xe1pido, antes que os rob\xf4s voltem!","{r}? I knew you'd come! Hurry, before the robots come back!","\xbf{r}? \xa1Sab\xeda que vendr\xedas! \xa1R\xe1pido, antes de que vuelvan los robots!"],t.w)
B.PI=new A.a5(B.a0,["{r}... senti sua energia. Esta jaula bloqueia meus poderes... me ajuda!","{r}... I felt your energy. This cage blocks my powers... help me!","{r}... sent\xed tu energ\xeda. Esta jaula bloquea mis poderes... \xa1ay\xfadame!"],t.w)
B.Pl=new A.a5(B.kB,[B.PN,B.PP,B.PK,B.PI],t.vb)
B.Pm=new A.a5(B.kB,[2,3,5,8],t.g)
